const D = { density:.5, scale:1, energy:.6, hue:32, speed:1, glow:.6, x:.5, y:.5, style:'paper', act:'release', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), lrp=(a,b,t)=>a+(b-a)*t, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360), st=P.style;
const paper=st==='paper', riso=st==='riso', ember=st==='ember', wire=st==='wireframe', noir=st==='noir';
const dens=clp(P.density,0,1), en=clp(P.energy,0,1)*(0.5+0.6*K.intensity), gl=clp(P.glow,0,1), spd=P.speed;

// ---- act dramaturgy (multi-minute) ----
let ascA=1, swayA=1, sizeA=1, popA=1;
if(P.act==='gust'){ swayA=2.4; ascA=1.15; popA=1; }
else if(P.act==='vigil'){ ascA=0.45; swayA=0.5; sizeA=1.5; popA=0.55; }
// gust: slow sideways pushes in waves
const gust = P.act==='gust' ? Math.sin(K.t*0.18)*0.5+Math.sin(K.t*0.37+1.3)*0.3 : 0;

const N = Math.max(3, Math.round(lrp(6,46,dens)*popA));
if(S.seedUsed!==P.seed || S.N!==N){
  S.seedUsed=P.seed; S.N=N; S.L=[];
  for(let i=0;i<N;i++) S.L.push({
    x0: fr(i*3.1+1), ph: fr(i*5.7+2), sp: 0.55+fr(i*7.3+3)*0.9,
    sz: 0.6+fr(i*9.1+4)*0.9, sway: 0.5+fr(i*2.2+5), hj: (fr(i*4.4+6)-0.5)*22,
    fk: fr(i*6.6+7)*TAU, lane: fr(i*8.8+8) });
}
const spreadC = P.x, baseW = 0.9;

// warm lantern color by height (hotter/brighter near flame)
function bodyCol(f, hj){
  if(ember){ const h=md(H+lrp(38,6,f)+hj*0.3,360); return [h, lrp(55,95,f), lrp(96,72,1-f)]; }
  return [md(H+hj+lrp(6,-6,f),360), lrp(58,84,f), lrp(96,70,f)];
}

const oldOp=drawingContext.globalCompositeOperation;

// draw one lantern at (lx,ly) size ls, alpha mult am, flicker fl
function lantern(lx,ly,ls,am,hj,fl,fgBlur){
  const bw=ls*0.62, bh=ls*0.92, rim=ls*0.30;
  // --- soft warm halo (additive) ---
  if(!wire){
    blendMode(ADD); noStroke();
    const hr=ls*(1.1+gl*2.4)*(0.85+0.3*fl);
    const ha=(noir?26:16)*am*(0.6+en*0.6+K.swell*0.4+A.bass*0.5);
    const hcol=ember?[md(H+14,360),80,100]:[md(H+6,360),70,100];
    for(let r=4;r>0;r--){ const tt=r/4; fill(hcol[0],hcol[1],hcol[2], clp(ha*(1-tt)*(1-tt),0,35)); ellipse(lx,ly-bh*0.1,hr*tt*2,hr*tt*2.1); }
    blendMode(BLEND);
  }
  if(noir){
    // chiaroscuro: form from a warm light core in darkness, no outline
    blendMode(ADD); noStroke();
    const cc=bodyCol(0.6,hj);
    for(let r=6;r>0;r--){ const tt=r/6; fill(cc[0],clp(cc[1]-tt*30,0,100),cc[2], clp(20*am*(1-tt)*(1-tt)*(0.7+0.5*fl),0,34)); ellipse(lx,ly-bh*0.12, bw*1.5*tt, bh*1.7*tt); }
    // dim shell hint (occlusion shadow lower edge)
    fill(md(H,360),40,18, 10*am); ellipse(lx,ly+bh*0.42, bw*1.2, bh*0.5);
    blendMode(BLEND);
    return;
  }
  push(); translate(lx,ly);
  const top=-bh*0.5, bot=bh*0.5;
  if(wire){
    // schematic wireframe lantern — glowing vector ribs + rims, no fill (abstract)
    const wc=[md(H+hj,360), 60, 100];
    stroke(wc[0],wc[1],wc[2], clp((70+30*fl)*am,0,100)); strokeWeight(Math.max(1,ls*0.02)); noFill();
    drawingContext.shadowBlur=ls*0.35; drawingContext.shadowColor='rgba(255,200,120,0.9)';
    // rims
    ellipse(0,top, rim*1.0, rim*0.34);
    ellipse(0,bot*0.86, rim*1.35, rim*0.42);
    // vertical ribs (curved)
    for(let k=-2;k<=2;k++){ const fx=k/2; noFill(); beginShape();
      vertex(fx*rim*0.5, top);
      bezierVertex(fx*rim*0.9, top+bh*0.3, fx*rim*0.85, bot*0.4, fx*rim*0.68, bot*0.86);
      endShape(); }
    // base cross + hanging flame dot
    line(-rim*0.5,bot*0.86, rim*0.5,bot*0.86);
    drawingContext.shadowBlur=ls*0.5; fill(md(H+10,360),70,100, 90*am); noStroke(); circle(0,bot*0.55, ls*0.10*(0.8+0.5*fl));
    drawingContext.shadowBlur=0;
    pop(); return;
  }
  // ---- paper / riso / ember: soft translucent shade, no hard cartoon outline ----
  noStroke();
  const c0=bodyCol(0.85,hj), c1=bodyCol(0.15,hj);
  const inks = riso ? [[md(H+2,360),82,96],[md(H+34,360),78,98]] : null;
  const passes = riso?2:1;
  for(let p=0;p<passes;p++){
    const ox = riso? (p===0?-ls*0.05:ls*0.05) : 0;
    const oy = riso? (p===0?-ls*0.03:ls*0.03) : 0;
    if(riso) blendMode(MULTIPLY);
    // vertical gradient body via stacked trapezoids
    const seg=6;
    for(let s2=0;s2<seg;s2++){
      const f0=s2/seg, f1=(s2+1)/seg;
      const y0=lrp(top,bot,f0), y1=lrp(top,bot,f1);
      const wprof=t=>bw*(0.62+0.44*Math.sin(t*Math.PI)); // barrel bulge
      const w0=wprof(f0), w1=wprof(f1);
      const col= riso? inks[p] : bodyCol(1-f0,hj);
      const a = riso? 62 : (ember? 70 : 82)*am;
      fill(col[0],col[1],col[2], a);
      quad(ox-w0,y0+oy, ox+w0,y0+oy, ox+w1,y1+oy, ox-w1,y1+oy);
    }
    if(riso) blendMode(BLEND);
  }
  // interior glow (flame seen through paper)
  blendMode(ADD); noStroke();
  const fc=bodyCol(0.0,hj);
  fill(fc[0],clp(fc[1]-20,0,100),100, clp(30*am*(0.7+0.6*fl),0,35)); ellipse(0,bh*0.18, bw*1.1, bh*0.7);
  blendMode(BLEND);
  // paper ribs / structure (fine texture, not outline)
  if(paper){
    stroke(md(H+hj,360),40,40, 22*am); strokeWeight(Math.max(0.6,ls*0.01)); noFill();
    for(let k=-2;k<=2;k++){ const fx=k/2.2; beginShape();
      vertex(fx*bw*0.9, top+bh*0.06);
      bezierVertex(fx*bw*1.05, -bh*0.1, fx*bw*1.05, bh*0.15, fx*bw*0.72, bot*0.9);
      endShape(); }
    // top + bottom rims
    stroke(md(H+hj-8,360),50,52,34*am); strokeWeight(Math.max(0.8,ls*0.016));
    line(-bw*0.5,top+bh*0.03,bw*0.5,top+bh*0.03);
    noStroke(); fill(md(H+hj,360),42,58, 40*am); ellipse(0,bot*0.9, bw*1.3, bh*0.14);
  }
  if(riso){
    // halftone dot texture (sparse, cheap) for print grain
    noStroke(); fill(md(H+18,360),20,20, 30*am);
    for(let dy=0;dy<5;dy++)for(let dx=0;dx<3;dx++){ const px=(dx-1)*bw*0.5, py=lrp(top,bot,dy/4); if(fr(dx*7+dy*13+1)>0.45) circle(px,py, ls*0.03); }
  }
  // tiny flame flicker at base
  blendMode(ADD); noStroke();
  const flc=[md(H+8,360),70,100];
  fill(flc[0],flc[1],flc[2], clp(60*am*(0.6+0.7*fl),0,80)); ellipse(0,bot*0.62, ls*0.09*(0.8+0.4*fl), ls*0.16*(0.9+0.5*fl));
  blendMode(BLEND);
  pop();
}

// ---- background lanterns (rising stream) ----
const ascRate=0.05*ascA;
for(let i=0;i<N;i++){
  const L=S.L[i];
  const life=frc(L.ph + K.t*ascRate*L.sp*spd);        // 0 bottom .. 1 top
  const depth=0.4+0.6*L.lane;                          // parallax: far small, near big
  const ly=Hh*1.08 - life*Hh*1.24;
  const swayX=Math.sin(K.t*0.4*L.sway*spd + L.fk)*u*0.05*swayA*(0.5+en) + gust*u*0.12*depth;
  const lx=W*(spreadC + (L.x0-0.5)*baseW)+swayX;
  const ls=u*0.085*P.scale*sizeA*L.sz*depth;
  const edge=clp(life*6,0,1)*clp((1-life)*4,0,1);      // fade in bottom, out top
  const fl=0.5+0.5*Math.sin(K.t*(2.4+L.sp*2)*spd+L.fk)*(0.6+0.4*en)+0.2*Math.sin(K.t*5.1+L.fk*2);
  if(edge<=0.01) continue;
  lantern(lx,ly,ls,edge*(0.55+0.5*depth), L.hj, clp(fl,0,1.4), false);
}

// ---- foreground drifter: one big lantern crosses horizontally (occasional) ----
const fgPer=42;                                        // ~long period
const fgPhase=frc(K.t/fgPer + P.seed*0.37);
const fgActive = fgPhase<0.6;                          // present 60% of the cycle, off-screen otherwise
if(fgActive && !wire){
  const cross=fgPhase/0.6;                             // 0..1 across screen
  const dir = (Math.floor(K.t/fgPer + P.seed*0.37)%2===0)?1:-1;
  const fx = dir>0 ? lrp(-0.15,1.15,cross)*W : lrp(1.15,-0.15,cross)*W;
  const fy = Hh*(0.28+0.14*Math.sin(cross*Math.PI)) + u*0.03*Math.sin(K.t*0.5);
  const fs = u*0.22*P.scale*(0.9+0.2*K.swell);
  const ffl=0.55+0.45*Math.sin(K.t*3.2+P.seed);
  lantern(fx,fy,fs, clp(Math.sin(cross*Math.PI)*1.2,0,1)*0.9, (fr(9)-0.5)*18, clp(ffl,0,1.3), true);
}

blendMode(BLEND); drawingContext.globalCompositeOperation=oldOp; drawingContext.shadowBlur=0; noStroke();
